import { useEffect, useState } from "react";
import { parseVcd } from "../lib/vcd";
import { apiUrl } from "../lib/api";

const MAX_SAMPLES = 40;

export default function Waveform({ artifactPath }) {
  const [parsed, setParsed] = useState(null);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (!artifactPath) return;
    setParsed(null);
    setError(null);
    fetch(apiUrl(`/api/artifact?path=${encodeURIComponent(artifactPath)}`))
      .then((r) => {
        if (!r.ok) throw new Error(`${r.status}`);
        return r.text();
      })
      .then((text) => setParsed(parseVcd(text)))
      .catch((e) => setError(String(e)));
  }, [artifactPath]);

  if (!artifactPath) return <div className="waveform-empty">No waveform yet</div>;
  if (error) return <div className="waveform-empty">Could not load waveform ({error})</div>;
  if (!parsed) return <div className="waveform-empty">Loading waveform…</div>;

  // vec is the sweep counter, not a real port -- everything else is a 1-bit signal
  const names = parsed.signals.filter((n) => n !== "vec");
  const samples = parsed.samples.slice(0, MAX_SAMPLES);

  return (
    <div className="waveform">
      <div className="waveform-rows">
        {names.map((name) => (
          <div className="waveform-row" key={name}>
            <span className="waveform-label">{name}</span>
            <div className="waveform-cells">
              {samples.map((s, i) => {
                const v = s.values[name];
                const on = v === "1";
                return (
                  <div
                    key={i}
                    className={`waveform-cell ${on ? "on" : "off"}`}
                    title={`t=${s.time} ${name}=${v ?? "?"}`}
                  />
                );
              })}
            </div>
          </div>
        ))}
      </div>
      {parsed.samples.length > MAX_SAMPLES && (
        <div className="waveform-note">
          showing first {MAX_SAMPLES} of {parsed.samples.length} vectors
        </div>
      )}
    </div>
  );
}

export const API_BASE = import.meta.env.VITE_API_BASE || "http://localhost:8000";

export function apiUrl(path) {
  return `${API_BASE}${path}`;
}

export async function startRun({ chip, attempts = 1 }) {
  const res = await fetch(apiUrl("/api/runs"), {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ chip, attempts }),
  });
  if (!res.ok) throw new Error(`start run failed: ${res.status}`);
  return res.json();
}

export async function fetchChips() {
  const res = await fetch(apiUrl("/api/chips"));
  if (!res.ok) throw new Error(`fetch chips failed: ${res.status}`);
  return res.json();
}

import { useEffect, useRef, useState } from "react";
import { apiUrl } from "./api";

const HISTORY_LIMIT = 500;

// Subscribes to the harness/orchestrator's structured event stream over SSE.
// UI state is derived ONLY from these JSON events -- never from parsing any
// Devin session's natural-language chatter.
export function useEvents() {
  const [events, setEvents] = useState([]);
  const [connected, setConnected] = useState(false);
  const sourceRef = useRef(null);

  useEffect(() => {
    const source = new EventSource(apiUrl("/api/events"));
    sourceRef.current = source;

    source.onopen = () => setConnected(true);
    source.onerror = () => setConnected(false);
    source.onmessage = (msg) => {
      try {
        const event = JSON.parse(msg.data);
        setEvents((prev) => {
          const next = [...prev, event];
          return next.length > HISTORY_LIMIT ? next.slice(next.length - HISTORY_LIMIT) : next;
        });
      } catch {
        // ignore malformed lines rather than crash the UI
      }
    };

    return () => source.close();
  }, []);

  return { events, connected };
}

const NODES = [
  { id: "coder", label: "Coder", agent: "coder" },
  { id: "harness1", label: "Harness", agent: "harness", gate: true },
  { id: "testbencher", label: "Testbencher", agent: "testbencher" },
  { id: "style", label: "Style", agent: "style" },
  { id: "synth", label: "Synth", agent: "synth" },
];

const STATUS_COLOR = {
  idle: "#475569",
  running: "#3b82f6",
  pass: "#22c55e",
  fail: "#ef4444",
  stalled: "#f59e0b",
  error: "#ef4444",
};

function latestByAgent(events) {
  const map = {};
  for (const e of events) {
    map[e.agent] = e;
  }
  return map;
}

export default function PipelineGraph({ events }) {
  const latest = latestByAgent(events);
  const lastEvent = events[events.length - 1];
  const activeAgent = lastEvent?.agent;

  return (
    <div className="pipeline-graph">
      {NODES.map((node, i) => {
        const event = latest[node.agent];
        const status = event?.status ?? "idle";
        const color = STATUS_COLOR[status] ?? STATUS_COLOR.idle;
        const isActive = node.agent === activeAgent;

        return (
          <div className="pipeline-node-wrap" key={node.id}>
            {i > 0 && (
              <div className={`pipeline-edge ${isActive ? "pipeline-edge-active" : ""}`}>
                <div className="pipeline-edge-line" />
                {isActive && <div className="pipeline-edge-pulse" />}
              </div>
            )}
            <div
              className={`pipeline-node ${node.gate ? "pipeline-node-gate" : ""} ${
                status === "running" ? "pipeline-node-running" : ""
              }`}
              style={{ "--node-color": color }}
              title={event?.detail ?? "no events yet"}
            >
              <div className="pipeline-node-dot" />
              <div className="pipeline-node-label">{node.label}</div>
              <div className="pipeline-node-status">{status}</div>
              {event?.total != null && (
                <div className="pipeline-node-count">
                  {event.passed}/{event.total}
                </div>
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
}

const STATUS_LABEL = {
  running: "RUNNING",
  pass: "PASS",
  fail: "FAIL",
  stalled: "STALLED",
  error: "ERROR",
};

export default function AgentStatus({ events }) {
  // Most recent event per (agent, stage) pair, newest first.
  const seen = new Set();
  const rows = [];
  for (let i = events.length - 1; i >= 0 && rows.length < 12; i--) {
    const e = events[i];
    const key = `${e.agent}:${e.stage}`;
    if (seen.has(key)) continue;
    seen.add(key);
    rows.push(e);
  }

  return (
    <div className="agent-status">
      <h3>Live Agent Status</h3>
      {rows.length === 0 && <div className="agent-status-empty">No activity yet</div>}
      {rows.map((e, i) => (
        <div className={`agent-status-row status-${e.status}`} key={i}>
          <div className="agent-status-top">
            <span className="agent-status-agent">{e.agent}</span>
            <span className="agent-status-stage">{e.stage}</span>
            <span className={`agent-status-badge badge-${e.status}`}>
              {STATUS_LABEL[e.status] ?? e.status}
            </span>
          </div>
          <div className="agent-status-detail">{e.detail}</div>
          {e.session_url && (
            <a className="agent-status-link" href={e.session_url} target="_blank" rel="noreferrer">
              view Devin session ↗
            </a>
          )}
        </div>
      ))}
    </div>
  );
}

import { useEffect, useState } from "react";
import Waveform from "./Waveform";
import { apiUrl } from "../lib/api";

function lastMatching(events, pred) {
  for (let i = events.length - 1; i >= 0; i--) {
    if (pred(events[i])) return events[i];
  }
  return null;
}

function TickingCount({ value }) {
  const [display, setDisplay] = useState(0);
  useEffect(() => {
    if (value == null) return;
    let raf;
    const start = display;
    const startTime = performance.now();
    const duration = 400;
    const step = (now) => {
      const t = Math.min(1, (now - startTime) / duration);
      setDisplay(Math.round(start + (value - start) * t));
      if (t < 1) raf = requestAnimationFrame(step);
    };
    raf = requestAnimationFrame(step);
    return () => cancelAnimationFrame(raf);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [value]);
  return <>{display}</>;
}

export default function ProofPanel({ events }) {
  const verifyEvent = lastMatching(events, (e) => e.stage === "verify" && e.total != null);
  const synthEvent = lastMatching(events, (e) => e.stage === "synthesize");
  const [synthReport, setSynthReport] = useState(null);

  useEffect(() => {
    if (!synthEvent?.artifact_path) {
      setSynthReport(null);
      return;
    }
    fetch(apiUrl(`/api/artifact?path=${encodeURIComponent(synthEvent.artifact_path)}`))
      .then((r) => (r.ok ? r.text() : null))
      .then(setSynthReport)
      .catch(() => setSynthReport(null));
  }, [synthEvent?.artifact_path]);

  const pct = verifyEvent && verifyEvent.total ? (verifyEvent.passed / verifyEvent.total) * 100 : 0;

  return (
    <div className="proof-panel">
      <h3>Proof</h3>

      <div className="proof-section">
        <div className="proof-section-title">Exhaustive vector verification</div>
        {verifyEvent ? (
          <>
            <div className="proof-vectors">
              <span className={`proof-count status-${verifyEvent.status}`}>
                <TickingCount value={verifyEvent.passed} />
              </span>
              <span className="proof-count-sep">/</span>
              <span className="proof-count-total">{verifyEvent.total}</span>
              <span className="proof-count-label">vectors passed</span>
            </div>
            <div className="proof-bar">
              <div
                className={`proof-bar-fill status-${verifyEvent.status}`}
                style={{ width: `${pct}%` }}
              />
            </div>
          </>
        ) : (
          <div className="proof-empty">No verification run yet</div>
        )}
      </div>

      <div className="proof-section">
        <div className="proof-section-title">Waveform (from simulation)</div>
        <Waveform artifactPath={verifyEvent?.artifact_path} />
      </div>

      <div className="proof-section">
        <div className="proof-section-title">FPGA synthesis (Yosys)</div>
        {synthEvent ? (
          <>
            <div className="proof-synth-summary">{synthEvent.detail}</div>
            {synthReport && (
              <pre className="proof-synth-report">{extractStatBlock(synthReport)}</pre>
            )}
          </>
        ) : (
          <div className="proof-empty">Not synthesized yet</div>
        )}
      </div>
    </div>
  );
}

function extractStatBlock(report) {
  const lines = report.split("\n");
  const idx = lines.map((l, i) => (l.trim().endsWith("cells") ? i : -1)).filter((i) => i >= 0);
  if (idx.length === 0) return report.slice(-800);
  const last = idx[idx.length - 1];
  return lines.slice(Math.max(0, last - 6), last + 4).join("\n");
}

import { useEffect, useState } from "react";
import { useEvents } from "./lib/useEvents";
import { startRun, fetchChips } from "./lib/api";
import PipelineGraph from "./components/PipelineGraph";
import AgentStatus from "./components/AgentStatus";
import ProofPanel from "./components/ProofPanel";

export default function App() {
  const { events, connected } = useEvents();
  const [chips, setChips] = useState([]);
  const [chip, setChip] = useState("74138");
  const [launching, setLaunching] = useState(false);
  const [launchError, setLaunchError] = useState(null);

  useEffect(() => {
    fetchChips()
      .then((d) => {
        setChips(d.chips);
        if (d.chips.length) setChip(d.chips[0]);
      })
      .catch(() => {});
  }, []);

  const branch = events.length ? events[events.length - 1].branch : null;

  async function handleLaunch() {
    setLaunching(true);
    setLaunchError(null);
    try {
      await startRun({ chip, attempts: 1 });
    } catch (e) {
      setLaunchError(String(e));
    } finally {
      setLaunching(false);
    }
  }

  return (
    <div className="app">
      <header className="app-header">
        <div className="app-title">
          <span className="app-title-mark">◆</span> CHIP RECREATION — COMMAND ROOM
        </div>
        <div className="app-header-right">
          {branch && <span className="app-branch">{branch}</span>}
          <span className={`conn-dot ${connected ? "conn-on" : "conn-off"}`} />
          <span className="conn-label">{connected ? "LIVE" : "DISCONNECTED"}</span>
        </div>
      </header>

      <div className="app-controls">
        <select value={chip} onChange={(e) => setChip(e.target.value)}>
          {chips.map((c) => (
            <option key={c} value={c}>
              {c}
            </option>
          ))}
        </select>
        <button onClick={handleLaunch} disabled={launching}>
          {launching ? "Launching…" : "Launch Attempt"}
        </button>
        {launchError && <span className="app-launch-error">{launchError}</span>}
      </div>

      <main className="app-main">
        <section className="app-graph-section">
          <PipelineGraph events={events} />
          <AgentStatus events={events} />
        </section>
        <section className="app-proof-section">
          <ProofPanel events={events} />
        </section>
      </main>
    </div>
  );
}

