// Hand-authored fixture used ONLY to performance/correctness-test the
// harness at 65536-vector scale before spending any Devin sessions on it.
module fpla_82s100_addr_decoder (
    input  A0, A1, A2, A3, A4, A5, A6, A7,
    input  A8, A9, A10, A11, A12, A13, A14, A15,
    output reg Y0, Y1, Y2, Y3, Y4, Y5, Y6, Y7
);
    wire [15:0] addr = {A15, A14, A13, A12, A11, A10, A9, A8,
                         A7, A6, A5, A4, A3, A2, A1, A0};
    wire [2:0] region = addr[15:13];
    wire in_carve = (addr >= 16'h6000) && (addr <= 16'h60FF);

    always @(*) begin
        {Y0, Y1, Y2, Y3, Y4, Y5, Y6, Y7} = 8'b1111_1111;
        if (region == 3'd7)
            Y7 = 1'b0;
        else if (in_carve)
            Y7 = 1'b0;
        else if (region == 3'd3)
            Y3 = 1'b0;
        else begin
            case (region)
                3'd0: Y0 = 1'b0;
                3'd1: Y1 = 1'b0;
                3'd2: Y2 = 1'b0;
                3'd4: Y4 = 1'b0;
                3'd5: Y5 = 1'b0;
                3'd6: Y6 = 1'b0;
            endcase
        end
    end
endmodule

